import{ContextMenuColumnSortClickEvent}from"./DataGridEvents.js";function toggleColumnVisibility(t,o){const e=!o.visible,n=t.data.columns.map((t=>(t===o&&(t.visible=e),t)));t.data={...t.data,columns:n}}export function addColumnVisibilityCheckboxes(t,o){const{columns:e}=t.data;for(const n of e)n.hideable&&o.defaultSection().appendCheckboxItem(n.title,(()=>{toggleColumnVisibility(t,n)}),n.visible)}export function addSortableColumnItems(t,o){const e=t.data.columns.filter((t=>!0===t.sortable));if(e.length>0)for(const n of e)o.defaultSection().appendItem(n.title,(()=>{t.dispatchEvent(new ContextMenuColumnSortClickEvent(n))}))}